/// <summary>
/// AVA
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(LedgerAllocationBasisRuleSource, LedgerAllocationBasisRuleSource_BasisCriteria), FormControlEventType::Lookup)]
public static void LedgerAllocationBasisRuleSource_BasisCriteria_OnLookup(FormControl sender, FormControlEventArgs e)
{
    LedgerAllocationBasisRuleSource          ruleSource = sender.formRun().dataSource(formDataSourceStr(LedgerAllocationBasisRuleSource,LedgerAllocationBasisRuleSource)).cursor();
    FormControlCancelableSuperEventArgs cancelableArgs = e as FormControlCancelableSuperEventArgs;

    if (ruleSource.FieldSetting == LedgerAllocationAccountDimension::SumAccount)
    {
        LedgerAllocationBAsisRuleSource::lookupSumMainAccounts(sender);

        cancelableArgs.CancelSuperCall();
    }
}
